dataset.rdf_kg_thres:
@prefix af-x: <http://purl.allotrope.org/ontologies/property#> .
@prefix agrontology: <http://aims.fao.org/aos/agrontology#> .
@prefix obo: <http://purl.obolibrary.org/obo/> .
@prefix qudt: <http://qudt.org/schema/qudt/> .
@prefix she: <https://soilwise-he.github.io/soil-health#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix sorelm: <http://sweetontology.net/relaMath/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

she:Alfalfa a skos:Concept ;
    skos:broader she:FodderCrop ;
    skos:prefLabel "alfalfa"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "6.8"^^xsd:float,
                "7.5"^^xsd:float ;
            sorelm:hasInterval "6.8-7.5" ] .

she:Barley a skos:Concept ;
    skos:broader she:Cereal ;
    skos:prefLabel "barley"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "7.5"^^xsd:float ;
            sorelm:hasInterval "6.8-7.5" ] ;
    she:hasTolerableSoilpH [ sorelm:hasInterval "5.7-7.5" ] .

she:Grassland a skos:Concept ;
    skos:prefLabel "grassland"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "6.3"^^xsd:float ] .

she:Maize a skos:Concept ;
    skos:altLabel "corn"@en ;
    skos:broader she:Cereal ;
    skos:prefLabel "maize"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "6.8"^^xsd:float ;
            sorelm:hasInterval "6.5-6.8" ] ;
    she:hasTolerableSoilpH [ sorelm:hasInterval "5.7-7.5" ] .

she:Oat a skos:Concept ;
    skos:broader she:Cereal ;
    skos:prefLabel "oat"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "7.5"^^xsd:float ;
            sorelm:hasInterval "5.7-7.5" ] ;
    she:hasTolerableSoilpH [ sorelm:hasInterval "5.0-7.5" ] .

she:Oilseed a skos:Concept ;
    skos:prefLabel "oilseed"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "7.0"^^xsd:float ] .

she:Pea a skos:Concept ;
    skos:prefLabel "pea"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "7.0"^^xsd:float ] .

she:Potato a skos:Concept ;
    skos:broader she:RootCrop ;
    skos:prefLabel "potato"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "6.0"^^xsd:float ] .

she:SoilpH a skos:Concept ;
    agrontology:greaterThan [ agrontology:isBeneficialFor she:CropProduction ;
            qudt:numericValue "6.0"^^xsd:float ],
        [ obo:RO_0002212 she:PhosphorusAvailability,
                she:ZincAvailability ;
            qudt:numericValue "7.0"^^xsd:float ] ;
    agrontology:smallerThan [ obo:RO_0002213 she:ZincAvailability ;
            qudt:numericValue "5.5"^^xsd:float ],
        [ obo:RO_0002212 she:PhosphorusAvailability ;
            qudt:numericValue "5"^^xsd:int ],
        [ agrontology:causes she:AluminiumRelease ;
            af-x:AFX_0000408 she:AgriculturalSoils ;
            qudt:numericValue "4.5"^^xsd:float ],
        [ obo:RO_0002212 she:CropProduction ;
            sorelm:hasInterval "5.5-6.0" ] ;
    sorelm:hasThreshold [ qudt:numericValue "4.5"^^xsd:float ;
            skos:related she:AluminiumToxicity ] ;
    sorelm:hasUpperBound [ obo:RO_0002212 she:CropYields ;
            obo:RO_0002213 she:Aluminium,
                she:Manganese ;
            qudt:numericValue "4.5"^^xsd:float ] ;
    skos:altLabel "soil pH value"@en ;
    skos:prefLabel "soil pH"@en .

she:Soybean a skos:Concept ;
    skos:altLabel "soya"@en ;
    skos:prefLabel "soybean"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "6.8"^^xsd:float ;
            sorelm:hasInterval "6.8-7.0" ] ;
    she:hasTolerableSoilpH [ sorelm:hasInterval "5.7-7.5" ] .

she:SugarBeet a skos:Concept ;
    skos:broader she:RootCrop ;
    skos:prefLabel "sugar beet"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "7.0"^^xsd:float ] .

she:Timothy a skos:Concept ;
    skos:broader she:FodderCrop ;
    skos:prefLabel "timothy"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "6.8"^^xsd:float ;
            sorelm:hasInterval "6.8-7.5" ] .

she:Wheat a skos:Concept ;
    skos:broader she:Cereal ;
    skos:prefLabel "wheat"@en ;
    she:hasOptimalSoilpH [ qudt:numericValue "6.8"^^xsd:float ;
            sorelm:hasInterval "6.8-7.5" ] ;
    she:hasTolerableSoilpH [ sorelm:hasInterval "5.7-7.5" ] .

she:FodderCrop a skos:Concept ;
    skos:prefLabel "fodder crop"@en .

she:RootCrop a skos:Concept ;
    skos:prefLabel "root crop"@en .

she:Cereal a skos:Concept ;
    skos:prefLabel "cereal"@en .
